export type ResumeOptimizerCategory =
  | "by profession"
  | "by experience level"
  | "by career situation"
  | "by resume section"
  | "by ATS platform"
  | "by industry"
  | "by country"
  | "by file format and workflow";

export type ResumeOptimizerSection = {
  id: string;
  heading: string;
  content: string[];
  bullets?: string[];
};

export type ResumeOptimizerFaq = {
  question: string;
  answer: string;
};

export type ResumeOptimizerLink = {
  href: string;
  label: string;
};

export type ResumeOptimizerPage = {
  slug: string;
  category: ResumeOptimizerCategory;
  title: string;
  metaTitle: string;
  metaDescription: string;
  h1: string;
  searchIntent: string;
  audience: string;
  intro: string;
  quickAnswer: string;
  sections: ResumeOptimizerSection[];
  benefits: string[];
  commonMistakes: string[];
  checklist: string[];
  keywords: string[];
  beforeAfter: {
    before: string;
    after: string;
    why: string;
  };
  faq: ResumeOptimizerFaq[];
  relatedSlugs: string[];
  resourceLinks: ResumeOptimizerLink[];
  primaryCta: ResumeOptimizerLink;
  secondaryCta: ResumeOptimizerLink;
};

type SeedInput = {
  slug: string;
  label: string;
  angle: string;
  keywords: string[];
  proof: string;
  before: string;
  after: string;
  why: string;
  mistakes: string[];
  relatedSlugs: string[];
};

type Seed = SeedInput & { category: ResumeOptimizerCategory };

