function titleCase(value: string) {
  return value.replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function buildFaq(seed: Seed): ResumeOptimizerFaq[] {
  const [first, second, third, fourth, fifth, sixth] = seed.keywords;
  return [
    {
      question: `What should a ${seed.label.toLowerCase()} resume optimizer improve first?`,
      answer: `Start with ${seed.angle}. Then check whether ${first} and ${second} appear in a way that is supported by real work, projects, or training. The first pass should improve the clearest evidence rather than rewrite every line.`,
    },
    {
      question: `Which ${seed.label.toLowerCase()} resume keywords are worth checking?`,
      answer: `Use the language that appears in the target vacancy and fits your experience. For this intent, useful starting points include ${[first, second, third].join(", ")}. Add ${fourth} or ${fifth} only when the resume can show how you used them.`,
    },
    {
      question: `How can I show ${seed.label.toLowerCase()} impact without making up numbers?`,
      answer: `${seed.proof} If a verified metric is available, add its scope and time period. If not, describe the decision, deliverable, quality check, or workflow change clearly; evidence does not have to be a percentage.`,
    },
    {
      question: `What is a common mistake on a ${seed.label.toLowerCase()} resume?`,
      answer: `The most common risk is ${seed.mistakes[0].toLowerCase()} A second review should catch ${seed.mistakes[1].toLowerCase()} and make sure ${sixth} is connected to a real example rather than a detached keyword.`,
    },
    {
      question: `Can CVBoosta optimize my ${seed.label.toLowerCase()} resume for one vacancy?`,
      answer: `Yes. Start with your current resume and one real job description, review the ATS and keyword signals, and keep only suggestions that remain truthful. CVBoosta helps organize the comparison; you decide which edits accurately represent your experience.`,
    },
  ];
}

function buildPage(seed: Seed, index: number): ResumeOptimizerPage {
  const category = CATEGORY_COPY[seed.category];
  const ctas = CTA_PAIRS[index % CTA_PAIRS.length];
  const query = seed.label.toLowerCase().includes("resume optimizer")
    ? seed.label
    : seed.label.toLowerCase().startsWith("resume ")
      ? `${seed.label} optimizer`
    : `${seed.label} resume optimizer`;
  const optimizerArticle = seed.label.startsWith("ATS") || (/^[aeiou]/i.test(seed.label) && !/^UX\b/i.test(seed.label)) ? "an" : "a";
  const subject = seed.label.toLowerCase().includes("resume")
    ? seed.label.toLowerCase()
    : `${optimizerArticle} ${seed.label.toLowerCase()} resume`;
  const titleSubject = seed.label.toLowerCase().includes("resume")
    ? titleCase(seed.label)
    : `${titleCase(seed.label)} Resume`;
  const titleFormulas = [
    `${query}: ATS Keywords and Job Match | CVboosta`,
    seed.label.toLowerCase().includes("resume optimizer")
      ? `Improve ${query} for ATS | CVboosta`
      : `Optimize Your ${titleSubject} for ATS | CVboosta`,
    `${query}: Improve Recruiter Clarity | CVboosta`,
    `${query}: Fix Weak Bullets and Keywords | CVboosta`,
  ];
  const metaTitle = seed.slug === "ats-resume-optimizer"
    ? "ATS Resume Optimizer: Improve Parsing and Match | CVboosta"
    : titleFormulas[index % titleFormulas.length];
  const h1Subject = seed.label.toLowerCase().includes("resume") ? `your ${subject}` : subject;
  const metaDescription = `${query}: ${seed.angle}. Check ATS keywords, tailor to a job description, and improve recruiter clarity with CVboosta.`;
  const intro = `${seed.label} candidates often need more than a polished template: ${seed.angle}. ${category.opening} This guide is for ${category.audience}.`;
  const quickAnswer = `${query} means comparing your current resume with the target work, improving the signals that matter for ${seed.keywords.slice(0, 3).join(", ")}, and rewriting only what you can support. For this intent, prioritize ${seed.proof.toLowerCase()}`;
  const sections: ResumeOptimizerSection[] = [
    {
      id: "what-to-improve",
      heading: `What this ${seed.label.toLowerCase()} resume optimizer should improve`,
      content: [
        `${seed.angle}. A useful first pass gives the reader a fast answer to three questions: what kind of work you do, where your experience fits this vacancy, and what evidence makes the claim believable.`,
        `${seed.proof} That makes the edit more useful than replacing every phrase with a more forceful synonym. Keep the original facts, choose the strongest recent examples, and let the target job description decide which details deserve the most space.`,
        `Use the following signals as an editing brief, not as a list to copy blindly. If one does not describe your real background, leave it out and look for a nearby, accurate example instead.`,
      ],
      bullets: seed.keywords.slice(0, 4),
    },
    {
      id: "role-specific-criteria",
      heading: `${titleCase(seed.label)} criteria recruiters can verify`,
      content: [
        `The strongest ${seed.label.toLowerCase()} resumes make the work inspectable. Name the setting, the responsibility, the decision or method, and the handoff or outcome where those facts are available. This creates a clear bridge between the vacancy and the experience section.`,
        `Prioritize ${seed.keywords.slice(0, 3).join(", ")} when they are relevant, but connect each term to a project, deliverable, customer, system, process, or team. A keyword on its own can help a search, yet a keyword with proof helps a recruiter trust the match.`,
        `If the target role is a step up or a transition, be explicit about the level of ownership. CVBoosta can surface gaps and wording options, but the final document should preserve the difference between supporting, coordinating, owning, and leading work.`,
      ],
      bullets: seed.keywords.slice(2),
    },
    {
      id: "keyword-and-proof",
      heading: "Keyword and proof checklist",
      content: [
        `Review the job description in three passes: recurring responsibilities, required or preferred skills, and the outcomes the employer appears to value. Then compare those groups with the words and examples already present in your resume. ${seed.proof}`,
        `Good optimization may change a heading, surface a supported synonym, move a relevant skill higher, or strengthen one recent bullet. It should not turn the document into a pasted vacancy or add ${seed.keywords[5]} merely because it appears in a search result.`,
      ],
      bullets: [
        `Use ${seed.keywords[0]} where the experience actually demonstrates it.`,
        `Connect ${seed.keywords[1]} to a decision, deliverable, or measurable scope.`,
        `Check ${seed.keywords[2]} in both the keyword map and the evidence section.`,
        "Remove claims that you could not explain in a real recruiter conversation.",
      ],
    },
    {
      id: "before-and-after",
      heading: `${titleCase(seed.label)} before and after example`,
      content: [
        `This example is intentionally realistic rather than dramatic. The after version adds context and proof while keeping the claim within the kind of fact a candidate can verify from their own work.`,
        seed.why,
      ],
    },
    {
      id: "optimization-process",
      heading: `A practical ${seed.label.toLowerCase()} resume optimization process`,
      content: [
        `Start with the resume you already use and one real vacancy. First check whether the file can be read in a normal text flow. Next, mark the vacancy's role language and compare it with your summary, skills, and most recent experience. Finally, rewrite the smallest number of lines that improves fit and clarity.`,
        `Run the result through a free ATS check when you want a quick diagnostic, then review every suggestion. The goal is a resume that is easier to parse and easier for a recruiter to believe, not a score that wins an argument with a tool.`,
      ],
      bullets: [
        "Start with the current resume and preserve truthful dates and titles.",
        "Paste the target job description and separate must-have from nice-to-have language.",
        `Improve the ${seed.keywords[0]} evidence before adding another keyword.`,
        "Read the finished version aloud and remove claims that sound bigger than the work.",
      ],
    },
    {
      id: "common-mistakes",
      heading: `Common ${seed.label.toLowerCase()} resume mistakes`,
      content: [
        `Most weak applications do not fail because one word is missing. They fail because the document makes the reader infer too much, mixes levels of responsibility, or gives more space to generic claims than to relevant evidence. Watch for these specific failure modes:`,
        `Fix the highest-cost issue first. A clean format cannot rescue a mismatch in role direction, and a long keyword list cannot rescue an experience section that does not show what you actually did.`,
      ],
      bullets: seed.mistakes,
    },
    {
      id: "final-checklist",
      heading: `Final checklist before you send this resume`,
      content: [
        `Before applying, compare the final document with the vacancy one more time. Confirm that the strongest relevant evidence appears early, that the file follows the employer's instructions, and that every keyword or metric is truthful.`,
      ],
      bullets: [
        ...seed.keywords.slice(0, 2).map((keyword) => `I can point to real evidence for ${keyword}.`),
        ...seed.mistakes.slice(0, 2).map((mistake) => `I checked that I did not ${mistake.charAt(0).toLowerCase() + mistake.slice(1)}`),
        "I reviewed the parsed text and the visible document on mobile or a smaller screen.",
      ],
    },
  ];

  return {
    slug: seed.slug,
    category: seed.category,
    title: seed.label,
    metaTitle,
    metaDescription,
    h1: seed.label.toLowerCase().includes("resume optimizer")
      ? `Improve ${h1Subject} for ATS and real recruiters`
      : `Optimize ${h1Subject} for ATS and real recruiters`,
    searchIntent: category.intent,
    audience: category.audience,
    intro,
    quickAnswer,
    sections,
    benefits: [
      `Make ${seed.keywords[0]} easier to find and verify`,
      `Connect ${seed.keywords[1]} to relevant evidence instead of a detached list`,
      `Give recruiters a clearer view of ${seed.keywords[2]} and the work behind it`,
      `Keep the application truthful while improving its match to one vacancy`,
    ],
    commonMistakes: seed.mistakes,
    checklist: [
      `The target role and ${seed.keywords[0]} are clear near the top`,
      `Recent experience demonstrates ${seed.keywords[1]} with context`,
      `The document is readable in normal text order`,
      `Every keyword and metric can be defended honestly`,
      `The final version follows the employer's file and application instructions`,
    ],
    keywords: seed.keywords,
    beforeAfter: { before: seed.before, after: seed.after, why: seed.why },
    faq: buildFaq(seed),
    relatedSlugs: seed.relatedSlugs,
    resourceLinks: category.resourceLinks,
    primaryCta: ctas.primary,
    secondaryCta: ctas.secondary,
  };
}

const expectedCategoryCounts: Record<ResumeOptimizerCategory, number> = {
  "by profession": 30,
  "by experience level": 8,
  "by career situation": 12,
  "by resume section": 15,
  "by ATS platform": 15,
  "by industry": 10,
  "by country": 4,
  "by file format and workflow": 6,
};

export const RESUME_OPTIMIZER_PAGES: ResumeOptimizerPage[] = ALL_SEEDS.map(buildPage);

export const RESUME_OPTIMIZER_CATEGORIES = Object.keys(expectedCategoryCounts) as ResumeOptimizerCategory[];

export function getResumeOptimizerPage(slug: string) {
  return RESUME_OPTIMIZER_PAGES.find((page) => page.slug === slug);
}

export function getResumeOptimizerPagesByCategory(category: ResumeOptimizerCategory) {
  return RESUME_OPTIMIZER_PAGES.filter((page) => page.category === category);
}

