export function validateResumeOptimizerPages(pages: ResumeOptimizerPage[]) {
  if (pages.length !== 100) {
    throw new Error(`Resume optimizer validation failed: expected exactly 100 pages, found ${pages.length}.`);
  }

  const assertUnique = (field: keyof Pick<ResumeOptimizerPage, "slug" | "metaTitle" | "h1" | "metaDescription" | "intro">) => {
    const seen = new Map<string, string>();
    for (const page of pages) {
      const value = page[field];
      const previousSlug = seen.get(value);
      if (previousSlug) {
        throw new Error(`Resume optimizer validation failed: duplicate ${field} on ${previousSlug} and ${page.slug}.`);
      }
      seen.set(value, page.slug);
    }
  };

  assertUnique("slug");
  assertUnique("metaTitle");
  assertUnique("h1");
  assertUnique("metaDescription");
  assertUnique("intro");

  const slugs = new Set(pages.map((page) => page.slug));
  const faqSignatures = new Map<string, string>();
  const validCtaHrefs = new Set([
    "/app",
    "/free-ats-resume-checker",
    "/cv-optimizer",
    "/pricing",
    "/register",
  ]);

  for (const page of pages) {
    if (page.sections.length < 5) {
      throw new Error(`Resume optimizer validation failed: ${page.slug} has fewer than 5 sections.`);
    }
    if (page.faq.length < 5) {
      throw new Error(`Resume optimizer validation failed: ${page.slug} has fewer than 5 FAQ items.`);
    }
    if (page.relatedSlugs.length < 3 || page.relatedSlugs.length > 6) {
      throw new Error(`Resume optimizer validation failed: ${page.slug} must have 3–6 related slugs.`);
    }
    const faqSignature = JSON.stringify(page.faq);
    if (faqSignatures.has(faqSignature)) {
      throw new Error(`Resume optimizer validation failed: FAQ copied between ${faqSignatures.get(faqSignature)} and ${page.slug}.`);
    }
    faqSignatures.set(faqSignature, page.slug);

    if (page.relatedSlugs.some((slug) => slug === page.slug)) {
      throw new Error(`Resume optimizer validation failed: ${page.slug} links to itself.`);
    }
    for (const relatedSlug of page.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(`Resume optimizer validation failed: ${page.slug} references missing related slug ${relatedSlug}.`);
      }
    }
    for (const cta of [page.primaryCta, page.secondaryCta]) {
      if (!validCtaHrefs.has(cta.href)) {
        throw new Error(`Resume optimizer validation failed: invalid CTA href ${cta.href} on ${page.slug}.`);
      }
    }
  }

  for (const [category, expected] of Object.entries(expectedCategoryCounts)) {
    const actual = pages.filter((page) => page.category === category).length;
    if (actual !== expected) {
      throw new Error(`Resume optimizer validation failed: ${category} should contain ${expected} pages, found ${actual}.`);
    }
  }
}

validateResumeOptimizerPages(RESUME_OPTIMIZER_PAGES);
